      "content": "/**\n * jev-guard — DSH adapter(native Cordis plugin)。\n *\n * A native hook in DSH is just an ordinary plugin subscribing to a canonical\n * lifecycle event, so this file is thin on purpose: 判定在 `lib/`(与调用方无关),\n * 这一半只做四件事:解析凭据、从工具调用里取出命令、应用重试预算、\n * 在 `tools/pre-execute` 上返回 typed PreToolDecision(allow / ask / deny 瀑布)。\n *\n * 它住在 `adapters/dsh/` 而不是 `lib/`,是**结构性声明**:判定不该知道谁在调用它 ——\n * 这样同一套判定才能被 CLI 与六份自检**离线复跑**(校准、回归、事故复盘全靠这一点)。\n * `lib/` 里没有任何 DSH 概念(没有 Cordis、没有 ctx、没有 PreToolDecision)。\n * 机制与映射见 docs/DSH-INTEGRATION.md。\n *\n * @module jev-guard/dsh\n */\n\nimport { randomUUID } from 'node:crypto'\nimport { readFileSync } from 'node:fs'\nimport { dirname, isAbsolute, join } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { flush, record } from '../../lib/audit.js'\nimport { DEFAULTS, evaluateCommand } from '../../lib/gate.js'\nimport { setLang, getLang, t } from '../../lib/i18n.js'\nimport { DEGRADING_KINDS, appliesTo, isSticky, kindLabel, readDegraded } from '../../lib/quota.js'\nimport { RetryBudget, fingerprint, reviseGuidance, toHostDecision } from '../../lib/verdict.js'\n\n/** Package root (adapters/dsh/ → ../..), so every adapter reads the same config.json. */\nconst ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..')\n\n/** CLI 入口绝对路径:写进拒绝理由里,让用户能直接复制粘贴授权命令(不用自己找路径)。 */\nconst CLI_PATH = join(ROOT, 'bin', 'guard.mjs')\n\n/** 插件 id:同时是 cordis 的 `name` 与会话 notice 的 `source.plugin`(去重靠它认自己的话)。 */\nconst PLUGIN_ID = 'jev-guard'\n\n/**\n * 本入口在降级状态里的身份(见 DEFAULTS.scope)。\n * 与 CLI 的 `'cli'` 必须不同:两边各自解析密钥,本地类状态(`no-key`)只该压制写下它的那条入口。\n */\nconst ADAPTER_SCOPE = 'dsh-adapter'\n\n/** notice 摘要的字符上限;与 DSH 的 CONTEXT_SUMMARY_MAX_CHARS 一致(超出会被折叠行截断)。 */\nconst SUMMARY_MAX = 120\n\n/**\n * 会话 notice 的 `source.kind` —— **生产者自有的** kind,不是 `'plugin'`。\n *\n * DSH 的会话格式 v4 把 v3 的 `{ kind: 'plugin', plugin: '<id>' }` 包装列为**退役写法**:\n * 读盘时 `source()` 直接拒(`format v4 message requires a producer-owned source kind`),\n * 而写盘那一步只校验\"kind 非空\" —— 于是坏消息**写得进去、读不回来**,表现是\n * 下次恢复会话时报 `SessionFormatError`(0.5.6 的真实缺陷,issue #1)。\n *\n * 值不是猜的:DSH 自己的 v3→v4 迁移函数 `producerKind()` 对**不认识的插件**的 fallback\n * 就是 `` `plugin:${plugin}` ``(见 `@deepseek-ai/dsh-session-format-v3-to-v4`)。\n * 照抄它,写出去的就与\"老会话迁移之后\"是同一种字节,而不是第三种形态。\n */\nconst NOTICE_SOURCE_KIND = `plugin:${PLUGIN_ID}`\n\n/**\n * Read config.json so there is ONE place to tune thresholds for every surface.\n * The cordis patch config still wins over it, and DEFAULTS lose to both.\n * @returns the file config, or an empty object.\n */\nfunction loadConfigFile() {\n  try {\n    return JSON.parse(readFileSync(join(ROOT, 'config.json'), 'utf8'))\n  } catch {\n    return {}\n  }\n}\n\n/** Cordis plugin name used by loader diagnostics. */\nexport const name = PLUGIN_ID\n\n/** The tool registry we gate and the credential seam we resolve the key from. */\nexport const inject = ['tools', 'credentials']\n\n/** Tool names gated by default. */\nconst DEFAULT_TOOLS = ['bash', 'pwsh']\n\n/**\n * Read the command out of a tool call, tolerating a string or object argument bag.\n * @param exec - the pre-execute pipeline view of the call.\n * @returns the command text, or undefined when this call carries none.\n */\nfunction extractCommand(exec) {\n  const args = exec?.arguments\n  const pick = bag => (typeof bag?.command === 'string' ? bag.command : undefined)\n  if (args && typeof args === 'object') return pick(args)\n  if (typeof args === 'string') {\n    try {\n      return pick(JSON.parse(args))\n    } catch {\n      return undefined\n    }\n  }\n  return undefined\n}\n\n/**\n * Resolve the TypeSafe key, highest precedence first:\n *\n *   1. `ctx.credentials.resolve(ref)` — DSH 自己的凭据存储(轮换后无需重启);\n *   2. the process environment;\n *   3. `apiKeyFile`(默认包根 `secrets.json`)—— `guard key set` 写的就是这一份。\n *\n * 第三层是必须的:适配器原先是**纯凭据层 + 环境变量**,而 `guard key set` 写的是文件 ——\n * 少了这一层,\"用 CLI 录入密钥\"对 DSH 用户就是一句空话。现在 CLI、适配器、文档三处\n * 共用同一条路径规则:相对路径按**包根**解析,与 cwd 无关。\n *\n * 值永不打印、永不进日志;下面只记\"哪一层命中\"。\n *\n * @param ctx - plugin context carrying the credential seam.\n * @param ref - environment-variable-style reference name.\n * @param cfg - effective config (`apiKeyFile` 决定第三层读哪个文件)。\n * @returns the secret value, or undefined when unconfigured.\n */\nasync function resolveKey(ctx, ref, cfg = {}) {\n  try {\n    const resolved = await ctx.credentials?.resolve?.(ref)\n    if (resolved?.value) return resolved.value\n  } catch (error) {\n    ctx.logger?.debug?.('jev-guard: credential resolution failed for %s: %s', ref, String(error?.message ?? error))\n  }\n  if (process.env[ref]) return process.env[ref]\n  try {\n    const configured = typeof cfg.apiKeyFile === 'string' && cfg.apiKeyFile.trim() !== '' ? cfg.apiKeyFile : undefined\n    const file = configured === undefined\n      ? join(ROOT, 'secrets.json')\n      : (isAbsolute(configured) ? configured : join(ROOT, configured))\n    const parsed = JSON.parse(readFileSync(file, 'utf8'))\n    const value = parsed[ref] ?? parsed.apiKey\n    if (typeof value === 'string' && value.trim() !== '') return value.trim()\n  } catch {\n    // 读不到就算了:预筛与 L0 仍然工作,语义层会因为 no-key 进入降级并在会话里说出来。\n  }\n  return undefined\n}\n\n/**\n * The session's effective approval policy.\n *\n * `danger-full-access` is `{ sandbox: 'danger-full-access', approval: 'never' }`,\n * and under `'never'` the approval service resolves EVERY ask to `rejected` — so\n * an `ask` there becomes a denial whose reason claims \"the user rejected tool\n * bash\". With `'never'` we therefore deny directly and explain why.\n *\n * @param ctx - plugin context.\n * @param agent - the agent on whose behalf the call runs.\n * @returns `'ask'` or `'never'`.\n */\nfunction effectivePolicy(ctx, agent) {\n  try {\n    const events = agent?.session?.snapshotEvents?.() ?? []\n    for (let i = events.length - 1; i >= 0; i -= 1) {\n      const event = events[i]\n      if (event?.type === 'approval/policy' && event?.data?.policy) return event.data.policy\n    }\n  } catch {\n    // fall through to the deployment default\n  }\n  return ctx.get?.('approval')?.config?.policy ?? 'ask'\n}\n\n/**\n * 会话当前的**权限 preset**(沙箱档位),例如 `workspace-write` / `danger-full-access`。\n *\n * 为什么要记它:DSH 的 preset 决定\"阀门后面还有没有别的兜底\"。`danger-full-access` 意味着\n * 没有文件沙箱、审批策略也是 `never` —— 那时**这条阀门就是唯一一层**,一条判错的代价最大。\n * 判定逻辑不需要它(阈值不该随档位偷偷变),但审计里必须有:事后回看一条高危决策时,\n * 第一个要问的问题就是\"当时后面还有没有沙箱\"。这也是 DSH 专用之后才拿得到的信息。\n *\n * @param ctx - plugin context.\n * @param agent - the agent on whose behalf the call runs.\n * @returns preset 名,或 undefined(读不到就不记,不编一个)。\n */\nfunction effectivePreset(ctx, agent) {\n  try {\n    const events = agent?.session?.snapshotEvents?.() ?? []\n    for (let i = events.length - 1; i >= 0; i -= 1) {\n      const event = events[i]\n      if (event?.type === 'permission/preset' && event?.data?.preset) return event.data.preset\n    }\n  } catch {\n    // 读不到就算了:preset 只是审计字段,不能因为它影响判定\n  }\n  return undefined\n}\n\n/**\n * 造一条 DSH 会话消息(`notice` 形态)。\n *\n * 形状必须与 DSH 的 `UserMessage` 一致,而且 `source` **只带这三个键**:`kind` / `form` / `summary`。\n *   · 多一个键会在**下次恢复会话**时被判成损坏 —— 也就是说这里写错能让用户的会话打不开;\n *   · 值为 `undefined` 的键不该出现(会破坏快照的\"可移植原样\"性质)—— 这是防御性规则,\n *     本插件的三个键永远都被填上。\n * 但**键的个数不是这份契约最容易错的地方,键的值才是**:0.5.6 把 `kind` 写成 `'plugin'`,\n * 键集完全正确,却是格式 v4 明令退役的写法 —— 写进去不报错,读的时候整条会话打不开\n * (issue #1)。所以这条契约不能靠\"比对键名\"来守,那正是 0.5.6 的测试漏掉它的原因;\n * 必须把产物交给**宿主自己的准入校验**:`tools/smoke-dsh-pipeline.mjs` 在真实的 DSH 管线里\n * 跑完一步之后,用 `assertV4RowAdmission`(持久化读盘时逐行调用的那个函数)校验本函数的产物。\n *\n * `id` 用 Node 自带的 `randomUUID`:DSH 的 id 是编译期 branded string,运行时就是一个普通字符串,\n * 所以我们不必为了这个字段去依赖它的包(本插件保持零依赖)。\n *\n * @param text - 正文(给模型看的完整内容)。\n * @param summary - 折叠行的标题(≤{@link SUMMARY_MAX} 字符)。\n * @returns 可直接追加进 pre-step 决策的消息对象。\n *\n * 导出是**刻意的**:形状是本插件与 DSH 之间最容易出错的一份契约(写错能让会话打不开),\n * 所以它必须能被一个\"在 DSH 自己的模块里跑\"的测试直接拿去校验。\n */\nexport function noticeMessage(text, summary) {\n  return {\n    id: randomUUID(),\n    role: 'user',\n    content: [{ type: 'text', text }],\n    source: {\n      kind: NOTICE_SOURCE_KIND,\n      form: 'notice',\n      summary: summary.length <= SUMMARY_MAX ? summary : `${summary.slice(0, SUMMARY_MAX - 1)}…`,\n    },\n  }\n}\n\n/**\n * 这条会话里我们已经说过哪些 notice(摘要集合)。\n *\n * 为什么不只在内存里记一个 `Set`:DSH 重启或会话恢复之后插件是一个全新实例,内存标记归零,\n * 于是已经写在会话历史里的提示会被**再说一遍**。会话历史是持久的,真相在那儿 ——\n * 扫自己发过的 notice 才是跨重启可靠的去重依据。\n *\n * **两种形态都要认。** 0.5.6 写的是 v3 的 `{ kind: 'plugin', plugin: 'jev-guard' }` 包装\n * (那份历史在 v4 宿主上根本读不出来,但在还停在 v3 的宿主上读得出来),现在的写的是\n * {@link NOTICE_SOURCE_KIND}。只认新形态会让升级前的历史被当成\"没说过\" —— 于是旧会话里\n * 每一条已经说过的话都会再说一遍。去重是**读历史**,所以读要宽、写要严。\n *\n * @param agent - the agent proposing the step.\n * @returns 已出现过的摘要集合。\n */\nfunction announcedSummaries(agent) {\n  const seen = new Set()\n  try {\n    for (const message of agent?.session?.deriveMessages?.() ?? []) {\n      const source = message?.source\n      if (typeof source?.summary !== 'string') continue\n      const own = source.kind === NOTICE_SOURCE_KIND\n        || (source.kind === 'plugin' && source.plugin === PLUGIN_ID)\n      if (own) seen.add(source.summary)\n    }\n  } catch {\n    // 读不到历史就当\"没说过\":宁可再说一遍,也不能漏掉\"没有密钥\"这条要求。\n  }\n  return seen\n}\n\n/**\n * 现在该不该说点什么(且还没说过)。\n *\n * 四种情形:① 本地可见的降级态是\"没有密钥\" → 要求录入;② 其它降级态 → 说明降级;\n * ③ 会话第一步且解析不到密钥(状态文件还没写) → 同样要求录入;④ 说过降级而现在已经恢复 → 宣布恢复。\n * 每种情形一句话、每个会话一次;成对出现(降级 → 恢复),不刷屏。\n *\n * @param ctx - plugin context.\n * @param cfg - effective config.\n * @param payload - the `agent/pre-step` payload.\n * @returns `{ text, summary }`,或 null(无话可说 / 已经说过)。\n */\nasync function pendingNotice(ctx, cfg, payload) {\n  const seen = announcedSummaries(payload?.agent)\n  const policy = t(cfg.degradePolicy === 'off' ? 'quota.policy.off' : 'quota.policy.l0-only')\n  const noKeySummary = t('notice.no-key.summary')\n  const recoveredSummary = t('notice.recovered.summary')\n  // 可枚举的降级摘要:只有这样才不用往消息里塞\"机器标记\"就能认出自己说过哪种状态。\n  const degradedSummaries = new Set(\n    DEGRADING_KINDS.map(kind => t('notice.degraded.summary', { label: kindLabel(kind), policy })),\n  )\n\n  const state = await readDegraded(cfg)\n  // 只认**本入口**该遵守的状态:CLI 写下的 no-key 不该在 DSH 会话里喊(反之亦然)。\n  const active = state !== null && appliesTo(state, cfg.scope) ? state : null\n\n  // 状态文件还没写时的\"首次没有密钥\":只在会话第一步解析一次密钥,免得每一步都去问凭据层。\n  // 会话中途失去密钥走另一条路 —— 那次受管命令判成 no-key 会写下状态,下一步就有人说话了。\n  let missingKey = false\n  if (active === null && payload?.turn === 1 && payload?.step === 1) {\n    missingKey = (await resolveKey(ctx, cfg.apiKeyEnv, cfg)) === undefined\n  }\n\n  let summary = null\n  if (active !== null && active.kind === 'no-key') summary = noKeySummary\n  else if (active !== null) summary = t('notice.degraded.summary', { label: kindLabel(active.kind), policy })\n  else if (missingKey) summary = noKeySummary\n  else if (!seen.has(recoveredSummary) && [...seen].some(s => s === noKeySummary || degradedSummaries.has(s))) {\n    // 只有这条会话确实说过\"降级 / 没有密钥\"才宣布恢复,否则每个健康会话开场都要多一句废话。\n    summary = recoveredSummary\n  }\n  if (summary === null || seen.has(summary)) return null\n\n  if (summary === noKeySummary) {\n    return { summary, text: `${summary}\\n\\n${t('notice.no-key.body', { cli: CLI_PATH })}` }\n  }\n  if (summary === recoveredSummary) {\n    return { summary, text: `${summary}\\n\\n${t('notice.recovered.body')}` }\n  }\n  // 恢复方式这句话与 `guard status` 共用同一条文案(粘性态没有倒计时,见 lib/quota.js)。\n  const recovery = active !== null && isSticky(active)\n    ? t('quota.status.degraded.sticky').trim()\n    : t('quota.status.degraded.recovery', {\n      mins: Math.round(Math.max(0, Number(active?.until ?? 0) - Date.now()) / 60000),\n    })\n  return {\n    summary,\n    text: `${summary}\\n\\n${t('notice.degraded.body', { label: kindLabel(active.kind), recovery, policy, cli: CLI_PATH })}`,\n  }\n}\n\n/**\n * Register the guard.\n * @param ctx - plugin context.\n * @param config - optional overrides; every field falls back to {@link DEFAULTS}.\n */\nexport function apply(ctx, config = {}) {\n  const cfg = {\n    ...DEFAULTS,\n    tools: DEFAULT_TOOLS,\n    apiKeyEnv: 'TYPESAFE_API_KEY',\n    retryLimit: 2,\n    ...loadConfigFile(),\n    ...config,\n    // 入口身份由代码定死:配置文件把它改乱,作用域隔离就失效了(见 ADAPTER_SCOPE)。\n    scope: ADAPTER_SCOPE,\n  }\n  // 语言在这里定一次:拒绝理由 / 弹窗正文 / 一次性令牌提示都是人读的文案。\n  // `lang: 'auto'`(默认)按 JEV_GUARD_LANG → locale 环境变量 → 系统 locale → zh-CN 解析。\n  // 注意它**不影响**发给 Jev 的那句问话 —— 那是 promptLang,默认仍是标定用的中文。\n  setLang(cfg.lang)\n\n  const cache = new (class {\n    constructor(limit) {\n      this.limit = limit\n      this.map = new Map()\n    }\n\n    get(k) {\n      const v = this.map.get(k)\n      if (v === undefined) return undefined\n      this.map.delete(k)\n      this.map.set(k, v)\n      return v\n    }\n\n    set(k, v) {\n      this.map.set(k, v)\n      while (this.map.size > this.limit) this.map.delete(this.map.keys().next().value)\n    }\n  })(cfg.cacheSize)\n  const budget = new RetryBudget(cfg.retryLimit)\n  const stats = { allowed: 0, revised: 0, blocked: 0, escalated: 0, prefilters: 0, cacheHits: 0, ruleHits: 0, errors: 0, degraded: 0 }\n  /** 已吼过的降级窗口(= kind + until),避免每个命令刷一遍屏。 */\n  let lastDegradedKey = ''\n  /** 已吼过的\"清不掉的状态文件\"(= 路径 + errno),同上。 */\n  let lastStuckClearKey = ''\n\n  ctx.logger?.info?.(\n    'jev-guard: gating %s (low=%s high=%s timeout=%sms key=%s lang=%s promptLang=%s)',\n    cfg.tools.join(','), cfg.lowThreshold, cfg.highThreshold, cfg.timeoutMs, cfg.apiKeyEnv,\n    getLang(), cfg.promptLang,\n  )\n\n  ctx.on('tools/pre-execute', async (exec, next) => {\n    try {\n      if (!cfg.tools.includes(exec.name)) return next()\n      const command = extractCommand(exec)\n      if (command === undefined) return next()\n\n      const apiKey = await resolveKey(ctx, cfg.apiKeyEnv, cfg)\n      const policy = effectivePolicy(ctx, exec.agent)\n      // 沙箱档位:只进审计,不参与判定(阈值不随档位偷偷变;见 effectivePreset 的说明)。\n      const preset = effectivePreset(ctx, exec.agent)\n      const cwd = typeof exec.arguments?.workdir === 'string'\n        ? exec.arguments.workdir\n        : (exec.agent?.session?.cwd ?? process.cwd())\n      const verdict = await evaluateCommand(command, { ...cfg, cwd, cache, apiKey, signal: exec.signal })\n\n      if (verdict.source === 'prefilter') stats.prefilters += 1\n      if (verdict.source === 'cache') stats.cacheHits += 1\n      if (verdict.source === 'static-rule') stats.ruleHits += 1\n      if (verdict.source === 'degraded') stats.degraded += 1\n      if (verdict.source === 'error') {\n        stats.errors += 1\n        ctx.logger?.warn?.('jev-guard: fail-open after %s (%sms): %s', verdict.error, verdict.ms, command.slice(0, 160))\n      }\n      // 降级告警:额度/密钥出问题时**必须有人能发现**。旧行为是静默 fail-open,\n      // 日志里一堆 error 但没人看得出\"它已经不在防护了\"。这里三件事一起做:\n      //   ① host 日志一条 warn(尽力而为);② 审计里留一条 level:'warn' 的记录(可靠);\n      //   ③ 非 allow 判定的理由里已经带了同一句(见 lib/verdict.js 的 warn)。\n      // 每个降级窗口最多吼一次,免得刷屏;人可以用 `guard status` 看全貌。\n      const degradedKey = verdict.degraded ? `${verdict.degraded.kind}:${verdict.degraded.until}` : ''\n      if (degradedKey && degradedKey !== lastDegradedKey) {\n        lastDegradedKey = degradedKey\n        ctx.logger?.warn?.('jev-guard: DEGRADED %s', verdict.warning)\n        void record({\n          level: 'warn', tool: exec.name, source: verdict.source, errorKind: verdict.errorKind,\n          degraded: verdict.degraded, warning: verdict.warning, cwd, command,\n          session: exec.agent?.session?.id,\n        }, cfg)\n      }\n\n      // 探测成功后状态文件却删不掉(只读文件系统 / 权限不足):服务确实回来了,但那份文件会\n      // 被每一次读取继续显示成\"已降级\"。它是人的环境问题,不是阀门的问题,所以走同一条\n      // \"有人能发现\"的路:host 日志一条 warn + 审计一条 level:'warn'(带上 errno 与路径)。\n      // 同一个(路径, errno)只吼一次 —— 否则每条命令都会重报同一件陈年旧事。\n      const stuckKey = verdict.clearFailed ? `${verdict.clearFailed.path}:${verdict.clearFailed.code ?? ''}` : ''\n      if (stuckKey && stuckKey !== lastStuckClearKey) {\n        lastStuckClearKey = stuckKey\n        ctx.logger?.warn?.('jev-guard: %s', verdict.warning)\n        void record({\n          level: 'warn', tool: exec.name, source: verdict.source, clearFailed: verdict.clearFailed,\n          warning: verdict.warning, cwd, command, session: exec.agent?.session?.id,\n        }, cfg)\n      }\n\n      const sessionKey = `${exec.agent?.session?.id ?? 'no-session'}:${fingerprint(command)}`\n      let effective = verdict\n\n      if (verdict.action === 'allow') {\n        stats.allowed += 1\n        budget.clear(sessionKey)\n        ctx.logger?.debug?.('jev-guard: allow via %s (p=%s, %sms)', verdict.source, verdict.p, verdict.ms)\n        // 审计:DSH 的 logger 会过滤 info 级,所以真实凭据落在 guard.log 里。\n        void record({\n          tool: exec.name, action: 'allow', decision: 'allow', source: verdict.source,\n          p: verdict.p, model: verdict.model, ms: verdict.ms, rule: verdict.rule?.id,\n          enriched: verdict.enriched, cwd, error: verdict.error, errorKind: verdict.errorKind,\n          policy, preset,\n          degraded: verdict.degraded, usage: verdict.usage, probe: verdict.probe,\n          recovered: verdict.recovered, command,\n          overridden: verdict.overridden, token: verdict.token,\n          session: exec.agent?.session?.id,\n        }, cfg)\n        return next()\n      }\n\n      // Blocked or merely uncertain: count attempts so a model that keeps\n      // rephrasing the same destruction eventually reaches a human instead of\n      // looping forever.\n      const { attempts, exhausted } = budget.hit(sessionKey)\n      // 例外:带 L0 `deny` 规则的硬命中**不能**借重试预算转人工 —— 那会让弹窗里的\"允许\"\n      // 越过硬地板(令牌不能越过 L0,审批同样不能,见 D5/D13)。硬命中照旧记 attempts 供审计。\n      const hardRule = verdict.rule?.kind === 'deny'\n      if (exhausted && verdict.action !== 'escalate' && hardRule !== true) {\n        effective = { ...verdict, action: 'escalate', source: `${verdict.source}+retry-budget` }\n      }\n      if (effective.action === 'revise') stats.revised += 1\n      else if (effective.action === 'block') stats.blocked += 1\n      else stats.escalated += 1\n\n      ctx.logger?.info?.(\n        'jev-guard: %s command (policy=%s, p=%s, attempts=%d, %sms, enriched=%s) %s',\n        effective.action, policy, verdict.p, attempts, verdict.ms,\n        (verdict.enriched ?? []).join('+') || 'none', command.slice(0, 160),\n      )\n\n      const decision = toHostDecision(command, effective, policy, {\n        token: verdict.token,\n        cliPath: CLI_PATH,\n        reviseInAskMode: cfg.reviseInAskMode,\n        blockInAskMode: cfg.blockInAskMode,\n      })\n      // 审计:被拦/被问/升级都要留痕(含命中规则与重试次数)。decision.kind 已经能区分\n      // \"转人工(ask)\"与\"直接拒(deny)\" —— 同一条 revise 在两种审批模式下会写在这里不同的值。\n      void record({\n        tool: exec.name, action: effective.action, decision: decision.kind, source: effective.source,\n        p: verdict.p, model: verdict.model, ms: verdict.ms, rule: verdict.rule?.id,\n        enriched: verdict.enriched, attempts, policy, preset, cwd, command,\n        errorKind: verdict.errorKind, degraded: verdict.degraded, warning: verdict.warning,\n        usage: verdict.usage, probe: verdict.probe,\n        overridden: verdict.overridden, token: verdict.token,\n        session: exec.agent?.session?.id,\n      }, cfg)\n      // revise 的两条出路都带上三种降级模板:转人工时它是**弹窗正文**(让做决定的人看清\n      // 还能怎么改),被直接拒时它是给模型的教案。routedToHuman 决定开头那几句怎么说。\n      if (effective.action === 'revise') {\n        return {\n          ...decision,\n          reason: reviseGuidance(command, effective, {\n            policy, token: verdict.token, cliPath: CLI_PATH, routedToHuman: decision.kind === 'ask',\n          }),\n        }\n      }\n      return decision\n    } catch (error) {\n      // Never let the valve break a turn: an unexpected failure delegates to the\n      // normal pipeline, where the sandbox and approval policy still apply.\n      stats.errors += 1\n      ctx.logger?.warn?.('jev-guard: unexpected failure, delegating: %s', String(error?.stack ?? error))\n      void record({ action: 'allow', decision: 'allow', source: 'adapter-error', error: String(error?.message ?? error), cwd: process.cwd() }, cfg)\n      return next()\n    }\n  })\n\n  // ── 会话内提示(纯 host 插件唯一能让用户真看到的渠道;见 docs/DECISIONS.md D15)──────────\n  //\n  // 为什么用 `agent/pre-step`:DSH 的 Settings / Plugins 页都由浏览器侧(`dsh.client`)注册占位,\n  // 纯 host 插件**没有任何** toast / banner / 启动提示接口;而注入一条 `notice` 消息会渲染成对话\n  // 里的一行(折叠标题 = summary,展开是正文)、**写进会话历史**、并且进入模型上下文 —— 于是\n  // \"这个阀门现在是瞎的\"既被人看见,也被模型知道。先例是同为 host-only 的\n  // `packages/guard/repeat-tool-reminder` 与 `packages/core/agent/src/model-selection.ts`。\n  if (cfg.notifyInSession !== false) {\n    ctx.on('agent/pre-step', async (payload, next) => {\n      const decision = await next()\n      try {\n        // 两条纪律,违反任何一条都会伤害宿主:\n        //  · 必须 `await next()` 之后再**追加** —— 决策里的 `messages` 是**替换**整个批次,\n        //    直接返回自己的数组会把用户这条消息吞掉;\n        //  · 空批次不要塞消息 —— 那会让循环白白多跑一次模型请求(DSH 自己的 model-selection\n        //    用的就是这条守卫)。\n        if (decision?.kind !== 'enter' || payload?.signal?.aborted) return decision\n        if (decision.messages.length === 0 && (payload.step === 1 || payload.messages?.length > 0)) return decision\n        const notice = await pendingNotice(ctx, cfg, payload)\n        if (notice === null) return decision\n        ctx.logger?.debug?.('jev-guard: in-session notice (%s)', notice.summary)\n        return { ...decision, messages: [...decision.messages, noticeMessage(notice.text, notice.summary)] }\n      } catch (error) {\n        // 这个监听器抛错会让**整次提案失败**(DSH 的行为),所以必须自己兜住:\n        // 说不上话是小事,把用户的一次对话搞坏是大事。\n        ctx.logger?.debug?.('jev-guard: notice skipped: %s', String(error?.message ?? error))\n        return decision\n      }\n    })\n  }\n\n  ctx.on('dispose', () => {\n    ctx.logger?.info?.('jev-guard: stopped (%j)', stats)\n    // 退出路径上等一次审计写入,避免进程结束时丢尾部记录。\n    void flush()\n  })\n}\n"
    },
    {
      "path": "lib/gate.js",
      "content": "/**\n * jev-guard — judge core(DSH-only 项目里仍然保持宿主无关的那一层)。\n *\n * 判定逻辑住在这里,与\"谁来调用它\"分开:同一个函数既被 DSH 插件在会话里调用,\n * 也被 `bin/guard.mjs` 与六份离线自检调用。**这不是为了支持多个宿主**(2026-09-20 已收窄为\n * DSH 专用,见 docs/DECISIONS.md D11),而是因为判定必须能被**离线复跑** ——\n * 校准、回归、事故复盘全靠这一点。\n *\n * Pipeline, in order:\n *   0. L0 static rules    -> block / escalate, no network, cannot be overridden\n *   1. deterministic prefilter -> allow, no network (read-only + rebuildable paths)\n *   2. Jev, ONE factual noul question -> allow / revise / block by two thresholds\n *   3. timeout, network error, aborted caller -> ALLOW (fail-open; the host's own\n *      sandbox and approval pipeline still sit in front of execution)\n *\n * 另外一层:**额度耗尽后的降级**(见 `./quota.js`)。这是收费 API,额度用完是必然事件。\n * 旧行为是\"每次调用各自 fail-open\" —— 功能没错,但会一直打注定失败的请求、日志被淹没、\n * 而且没有任何人会发现阀门已经瞎了。现在改成:持久性失败(quota / auth / no-key)写一份\n * 状态文件、在冷却窗口内不再发请求、窗口到期放**一次**探测;降级期间默认**只跑免费的\n * L0 + 预筛**(`degradePolicy: 'l0-only'`),并把这个事实写进理由、审计与 `guard status`。\n *\n * The question form is not arbitrary: a 114-item calibration run (2026-09-20)\n * measured this exact noul phrasing at 12/12 on destructive-command cases in\n * Chinese, while judgement-style forms were far weaker (action choice 75%,\n * risk band 50%). See docs/MEASUREMENTS.md.\n */\n\nimport { readFile, stat } from 'node:fs/promises'\nimport { dirname as dirname_, isAbsolute, join as joinPath, resolve as resolvePath } from 'node:path'\nimport {\n  DEGRADING_KINDS, classifyFailure, clearDegraded, enterDegraded, isDegraded, isSticky, probeDue, readDegraded, warningLine,\n} from './quota.js'\nimport { FALLBACK_LANG, normalizeLang, t, tIn } from './i18n.js'\nimport { staticRule } from './rules.js'\nimport { commandToken, consumeToken } from './token.js'\n\n/** Question id sent to Jev; it is echoed back as the answer key. */\nexport const QUESTION_ID = 'destroys_data'\n\n/** Languages the question can be asked in. */\nexport const PROMPT_LANGS = Object.freeze(['zh-CN', 'en'])\n\n/**\n * The noul question, in the language it should be asked in.\n *\n * **This is not UI text.** `promptLang` defaults to `zh-CN` — the language the\n * thresholds were calibrated in (114 labelled cases; Chinese input measured as good\n * as or better than translated English) — and it is deliberately independent of\n * `lang`, so switching the interface to English does not silently move a measured\n * decision boundary. Changing it is a re-calibration event, not a translation.\n *\n * @param promptLang - `'zh-CN' | 'en'`; anything else falls back to `zh-CN`.\n * @returns the frozen question object.\n */\nexport function judgeQuestion(promptLang = FALLBACK_LANG) {\n  const lang = normalizeLang(promptLang) ?? FALLBACK_LANG\n  return Object.freeze({\n    type: 'noul',\n    instructions: tIn(lang, 'gate.question.instructions'),\n    criteria: Object.freeze({\n      true: tIn(lang, 'gate.question.true'),\n      false: tIn(lang, 'gate.question.false'),\n    }),\n  })\n}\n\n/** The calibrated default question, kept as a convenience for probes and docs. */\nexport const QUESTION = judgeQuestion('zh-CN')\n\nexport const DEFAULTS = Object.freeze({\n  /**\n   * Language of everything a user or a model reads: verdict reasons, CLI output,\n   * degradation warnings, rule reasons. `'auto'` resolves from `JEV_GUARD_LANG`,\n   * then the POSIX locale variables, then the system locale, then `zh-CN`\n   * (see lib/i18n.js). It never changes the question asked to Jev — that is\n   * `promptLang`, on purpose.\n   */\n  lang: 'auto',\n  /**\n   * Language of the question sent to Jev **and** of the state keys it reads.\n   * Defaults to the calibrated Chinese question; see {@link judgeQuestion}.\n   */\n  promptLang: 'zh-CN',\n  /** Below this probability: allow. */\n  lowThreshold: 0.5,\n  /** At or above this probability: block. In between: revise. */\n  highThreshold: 0.7,\n  timeoutMs: 1800,\n  cacheSize: 256,\n  model: 'jev-latest',\n  endpoint: 'https://api.typesafe.ai/v1/systemone',\n  /** Read an invoked script's body into the state (closes the opaque-script blind spot). */\n  inlineScripts: true,\n  /** Ceiling for inlined script text. */\n  maxScriptBytes: 8192,\n  /** 额度/密钥类失败后的冷却时长(毫秒);见 ./quota.js。 */\n  quotaCooldownMs: 15 * 60 * 1000,\n  authCooldownMs: 30 * 60 * 1000,\n  /** 降级期间:`'l0-only'`(默认)= 只停联网语义层,L0 + 预筛照跑;`'off'` = 整条阀门暂停。 */\n  degradePolicy: 'l0-only',\n  /** 降级状态文件;空串 = 默认 `<JEV_GUARD_HOME>/degraded.json`。 */\n  degradedPath: '',\n  /**\n   * 本入口的身份,写进\"本地类\"降级状态(目前只有 `no-key`)。\n   *\n   * 为什么需要它:`no-key` 是**本地配置**状况(密钥解析各入口独立 —— DSH 插件走\n   * `ctx.credentials` / 环境变量 / 包根 `secrets.json`,CLI 走环境变量 / 那个文件),\n   * 而 degraded.json 是**全机共享**的文件。不记身份的话,某条入口读不到密钥就会把\n   * **密钥其实是好的**其它入口一起按停。服务侧状态(quota / auth)一律记 `global`。\n   */\n  scope: 'default',\n  /**\n   * 把降级、以及\"没有解析到密钥\"这两件事**在会话里说出来**(DSH 适配器在 `agent/pre-step`\n   * 上注入一条 notice)。纯 host 插件没有任何 toast / banner / 启动提示接口 —— 注入会话消息\n   * 是唯一能让用户真看到的渠道;设 false 则只保留 logger 与审计日志。\n   */\n  notifyInSession: true,\n  /** 成本估算单价(美元 / 百万输入 token);输出按官方说明免费。 */\n  pricePerMTok: 0.042,\n  /**\n   * 审批策略为 `ask`(宿主真的会弹审批框)时,`revise`(lowThreshold ≤ p < highThreshold)\n   * 怎么处置:`'ask'`(默认)= 转人工审批,`'deny'` = 直接拒绝。\n   *\n   * 为什么默认转人工:灰区本来就\"证据不足\",而 ask 模式下**人就在场**;直接拒绝等于让\n   * 一个 50% 的判断替人做决定。宿主没有应答者时审批是 fail-closed,不会出现无人自动放行。\n   */\n  reviseInAskMode: 'ask',\n  /**\n   * 同上,但针对 `block`(p ≥ highThreshold,由 Jev 语义层给出)。\n   * **不适用于 L0 的 `deny` 类硬规则**:那条路两种模式都拦死,见 toHostDecision。\n   */\n  blockInAskMode: 'ask',\n})\n\n/* ------------------------------------------------------------------ *\n * 1. deterministic read-only prefilter\n * ------------------------------------------------------------------ */\n\n/** Shell metacharacters that make a command more than one simple statement. */\nconst META = /[;&|<>`$()\\n]/\n\n/** First tokens that cannot mutate anything on their own. */\nconst PURE_READONLY = new Set([\n  'ls', 'cat', 'head', 'tail', 'wc', 'grep', 'rg', 'ps', 'df', 'du', 'free', 'uptime',\n  'whoami', 'pwd', 'echo', 'printf', 'date', 'which', 'type', 'printenv', 'stat', 'file',\n  'md5sum', 'sha256sum', 'shasum', 'tree', 'jq', 'sort', 'uniq', 'cut', 'tr', 'basename',\n  'dirname', 'realpath', 'readlink', 'id', 'hostname', 'uname', 'lscpu', 'nproc', 'ss',\n  'netstat', 'lsblk', 'lsof', 'timedatectl', 'who', 'groups', 'true', 'false', 'test',\n  'diff', 'cmp', 'column', 'paste', 'fold', 'nl', 'od', 'xxd', 'strings', 'less', 'more',\n  'man', 'info', 'es', 'codegraph', 'vol',\n])\n\n/** Read-only shapes for tools that are only sometimes read-only. */\nconst READONLY_SHAPE = [\n  /^sed\\s+-n\\b(?!.*\\s-i\\b)/, // sed -n without -i\n  /^find\\s+(?![^|]*-(delete|exec|execdir|ok|okdir|fprint|fprint0|fls)\\b)/,\n  /^journalctl\\s+(?!.*--vacuum)/,\n  /^git\\s+(-C\\s+\\S+\\s+)?(status|log|diff|show|blame|shortlog|rev-parse|rev-list|ls-files|ls-tree|cat-file|describe|reflog|count-objects|whatchanged|grep|fetch)\\b/,\n  /^git\\s+(-C\\s+\\S+\\s+)?branch\\s*(--list|-a|-r|-v|--show-current|--contains)?\\s*$/,\n  /^git\\s+(-C\\s+\\S+\\s+)?(remote\\s+(-v|show)|config\\s+--(get|list)|stash\\s+list|tag\\s+-l\\b|tag\\s+--list|worktree\\s+list)\\b/,\n  /^docker\\s+(ps|images|logs|inspect|version|info|stats|top|diff|port|history)\\b/,\n  /^docker\\s+compose\\s+(ps|logs|config|top)\\b/,\n  /^kubectl\\s+(get|describe|logs|version|explain|api-resources|top)\\b/,\n  /^kubectl\\s+config\\s+(view|current-context)\\b/,\n  /^systemctl\\s+(status|is-active|is-enabled|is-failed|list-units|list-unit-files|show|cat|--version)\\b/,\n  /^(npm|pnpm|yarn)\\s+(ls|list|why|view|outdated|config\\s+get|--version|-v)\\b/,\n  /^(node|python3?|pip3?|deno|bun|rustc|go|cargo|tsc)\\s+(--version|-v|list|show|freeze)\\s*$/,\n  /^cargo\\s+(tree|metadata)\\b/,\n  /^go\\s+(version|env|list)\\b/,\n]\n\n/** Directories whose deletion is cache/build housekeeping rather than data loss. */\nconst SAFE_ROOT = /^(\\/tmp\\/|\\/var\\/tmp\\/|~\\/\\.cache\\/|\\$HOME\\/\\.cache\\/|\\/home\\/[^/]+\\/\\.cache\\/)/\nconst SAFE_SEGMENT = /(\\/|^)(node_modules|dist|build|\\.next|__pycache__|\\.pytest_cache|target\\/debug|target\\/release)(\\/|$)/\nconst NEVER_SAFE = new Set(['/', '/*', '~', '$HOME', '.', '..', '*', '~/*'])\n\n/**\n * Strip quoted substrings so a `>` inside a grep pattern is not read as a redirect.\n * @param command - raw command text.\n * @returns the command with quoted regions blanked out.\n */\nexport function stripQuoted(command) {\n  return command.replace(/'[^']*'/g, \"''\").replace(/\"[^\"]*\"/g, '\"\"')\n}\n\n/**\n * Whether a command is provably read-only (safe to allow without asking Jev).\n * Deliberately conservative: anything ambiguous falls through to Jev.\n * @param command - raw command text.\n * @returns a human-readable reason when read-only, otherwise undefined.\n */\nexport function readOnlyReason(command) {\n  const raw = command.trim()\n  if (raw.length === 0) return 'empty command'\n  const s = stripQuoted(raw)\n  if (META.test(s)) return undefined\n  const head = s.split(/\\s+/)[0]\n  if (PURE_READONLY.has(head)) {\n    // `cat`-style readers cannot mutate; `es`/`codegraph` are index readers.\n    if (head === 'printenv' || head === 'type' || head === 'command') return `read-only (${head})`\n    return `read-only (${head})`\n  }\n  for (const re of READONLY_SHAPE) if (re.test(s)) return `read-only shape (${head})`\n  return undefined\n}\n\n/**\n * Whether a `rm` command only targets rebuildable locations.\n * @param command - raw command text.\n * @returns a reason when every target is rebuildable, otherwise undefined.\n */\nexport function safeDeleteReason(command) {\n  const raw = command.trim()\n  if (!/^rm\\s/.test(raw)) return undefined\n  const s = stripQuoted(raw)\n  if (META.test(s)) return undefined\n  const parts = s.split(/\\s+/).slice(1)\n  const targets = []\n  for (const p of parts) {\n    if (p === 'rm') continue\n    if (p.startsWith('-')) continue\n    targets.push(p)\n  }\n  if (targets.length === 0) return undefined\n  for (const t of targets) {\n    if (NEVER_SAFE.has(t)) return undefined\n    if (t.includes('..')) return undefined\n    if (SAFE_ROOT.test(t) || SAFE_SEGMENT.test(t)) continue\n    return undefined\n  }\n  return `rm on rebuildable path(s): ${targets.join(' ')}`\n}\n\n/**\n * Run both deterministic prefilter rules, including compound commands: when a\n * command is a sequence of `;` / `&&` / `||` / `|` segments and *every* segment\n * is provably harmless on its own, the whole command is harmless. One unsafe\n * segment makes the whole command go to Jev.\n * @param command - raw command text.\n * @returns a reason string when the command is provably harmless, else undefined.\n */\nexport function prefilter(command) {\n  const direct = readOnlyReason(command) ?? safeDeleteReason(command)\n  if (direct) return direct\n  const segments = stripQuoted(command.trim()).split(/\\s*(?:;|&&|\\|\\||\\||\\n)\\s*/).filter(Boolean)\n  if (segments.length < 2) return undefined\n  const reasons = segments.map(s => readOnlyReason(s) ?? safeDeleteReason(s))\n  if (reasons.some(r => r === undefined)) return undefined\n  return `compound of ${segments.length} harmless segments`\n}\n\n/* ------------------------------------------------------------------ *\n * 2. verdict cache\n * ------------------------------------------------------------------ */\n\n/** Minimal LRU keyed by exact command text. */\nexport class VerdictCache {\n  /**\n   * @param limit - maximum retained entries.\n   */\n  constructor(limit = DEFAULTS.cacheSize) {\n    this.limit = Math.max(1, limit)\n    this.map = new Map()\n  }\n\n  /**\n   * @param key - command text.\n   * @returns the cached verdict, or undefined.\n   */\n  get(key) {\n    const v = this.map.get(key)\n    if (v === undefined) return undefined\n    this.map.delete(key)\n    this.map.set(key, v)\n    return v\n  }\n\n  /**\n   * @param key - command text.\n   * @param value - verdict to retain.\n   */\n  set(key, value) {\n    this.map.set(key, value)\n    while (this.map.size > this.limit) this.map.delete(this.map.keys().next().value)\n  }\n\n  /** @returns current entry count. */\n  get size() {\n    return this.map.size\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 3. state enrichment — the \"my own script did something irreversible\" case\n * ------------------------------------------------------------------ */\n\n/** Interpreters whose file argument can be read and judged by its content. */\nconst INTERPRETERS = new Set([\n  'node', 'python', 'python3', 'bash', 'sh', 'zsh', 'dash', 'deno', 'bun',\n  'tsx', 'ts-node', 'ruby', 'perl', 'php', 'lua', 'Rscript',\n])\n\n/** Tokens that look like a script file rather than a flag or a subcommand. */\nconst LOOKS_LIKE_SCRIPT = /\\.(mjs|cjs|js|ts|mts|cts|jsx|tsx|py|sh|bash|zsh|rb|pl|php|lua)$/i\n\n/** Package-manager subcommands that never name a user script. */\nconst PM_BUILTINS = new Set([\n  'install', 'add', 'remove', 'rm', 'update', 'up', 'upgrade', 'i', 'ci', 'exec', 'dlx', 'x',\n  'why', 'ls', 'list', 'view', 'outdated', 'config', 'publish', 'pack', 'create', 'init',\n  'link', 'unlink', 'prune', 'store', 'audit', 'licenses', 'import', 'patch', 'deploy',\n])\n\n/**\n * Paths whose contents must never leave the machine, so they are never inlined\n * into the state sent to the API.\n */\nconst SENSITIVE_PATH = /(^|\\/)(\\.env(\\..*)?|\\.ssh|\\.gnupg|\\.aws|\\.config\\/gh|id_rsa.*|id_ed25519.*|.*\\.pem|.*\\.key|.*credential.*|.*secret.*|.*token.*)$/i\n\n/**\n * Split a command on `;` / `&&` / `||` / `|` while keeping the original quoting.\n * @param command - raw command text.\n * @returns the raw segments.\n */\nfunction splitRaw(command) {\n  return command.split(/\\s*(?:;|&&|\\|\\||\\|)\\s*/).filter(s => s.trim() !== '')\n}\n\n/**\n * Quote-aware whitespace tokenizer.\n * @param segment - one raw command segment.\n * @returns tokens with quotes removed.\n */\nfunction tokenize(segment) {\n  const tokens = []\n  const re = /\"([^\"]*)\"|'([^']*)'|(\\S+)/g\n  let m\n  while ((m = re.exec(segment)) !== null) tokens.push(m[1] ?? m[2] ?? m[3])\n  return tokens\n}\n\n/**\n * Find the script file a command would execute, if any.\n * @param command - raw command text.\n * @returns the script path as written (possibly relative), or undefined.\n */\nexport function scriptTarget(command) {\n  const first = splitRaw(command)[0]\n  if (first === undefined) return undefined\n  const tokens = tokenize(first)\n  let i = 0\n  while (i < tokens.length && ['sudo', 'env', 'command', 'nohup', 'time'].includes(tokens[i])) i += 1\n  const head = tokens[i]\n  if (head === undefined) return undefined\n\n  if (INTERPRETERS.has(head)) {\n    for (let j = i + 1; j < tokens.length; j += 1) {\n      const t = tokens[j]\n      if (t.startsWith('-')) continue\n      return LOOKS_LIKE_SCRIPT.test(t) ? t : undefined // `node -e \"...\"` has no file\n    }\n    return undefined\n  }\n\n  if (['pnpm', 'npm', 'yarn', 'bunx', 'npx'].includes(head)) {\n    for (let j = i + 1; j < tokens.length; j += 1) {\n      const t = tokens[j]\n      if (t === '--' || ['exec', 'dlx', 'x', 'run'].includes(t)) continue\n      if (t.startsWith('-')) continue\n      if (INTERPRETERS.has(t)) continue\n      return LOOKS_LIKE_SCRIPT.test(t) ? t : undefined\n    }\n    return undefined\n  }\n\n  if (LOOKS_LIKE_SCRIPT.test(head) && (head.startsWith('./') || head.startsWith('/') || head.includes('/'))) return head\n  return undefined\n}\n\n/**\n * Find the package.json script a command would run.\n * @param command - raw command text.\n * @returns the script name, or undefined.\n */\nexport function packageScriptName(command) {\n  const first = splitRaw(command)[0]\n  if (first === undefined) return undefined\n  const tokens = tokenize(first)\n  const head = tokens[0]\n  if (head === undefined || !['pnpm', 'npm', 'yarn', 'bun'].includes(head)) return undefined\n  if (tokens[1] === 'run' || tokens[1] === 'run-script') return tokens[2]?.startsWith('-') ? undefined : tokens[2]\n  const candidate = tokens[1]\n  if (candidate === undefined || candidate.startsWith('-') || PM_BUILTINS.has(candidate)) return undefined\n  return candidate\n}\n\n/**\n * Read a file as text when it is small, textual and not sensitive.\n * @param path - absolute path to read.\n * @param maxBytes - size ceiling.\n * @returns the text, or a short reason why it was skipped.\n */\nasync function readSmallText(path, maxBytes, promptLang = FALLBACK_LANG) {\n  if (SENSITIVE_PATH.test(path)) return { skipped: tIn(promptLang, 'gate.skip.sensitive') }\n  try {\n    const info = await stat(path)\n    if (!info.isFile()) return { skipped: tIn(promptLang, 'gate.skip.notFile') }\n    if (info.size > maxBytes) return { skipped: tIn(promptLang, 'gate.skip.tooLarge', { bytes: info.size }) }\n    const text = await readFile(path, 'utf8')\n    if (text.includes('\\u0000')) return { skipped: tIn(promptLang, 'gate.skip.binary') }\n    return { text }\n  } catch (error) {\n    return { skipped: tIn(promptLang, 'gate.skip.readError', { error: error?.code ?? error?.message ?? error }) }\n  }\n}\n\n/**\n * Resolve the nearest `package.json` scripts entry by walking up from a directory.\n * @param name - script name.\n * @param cwd - starting directory.\n * @returns the script body, or undefined.\n */\nasync function lookupPackageScript(name, cwd) {\n  let dir = cwd\n  for (let depth = 0; depth < 8; depth += 1) {\n    try {\n      const raw = await readFile(joinPath(dir, 'package.json'), 'utf8')\n      const body = JSON.parse(raw)?.scripts?.[name]\n      if (typeof body === 'string') return body\n    } catch {\n      // keep walking up\n    }\n    const parent = dirname_(dir)\n    if (parent === dir) break\n    dir = parent\n  }\n  return undefined\n}\n\n/**\n * Build the `state` object sent to Jev, enriching an opaque script invocation\n * with the script body (the one blind spot measured on 2026-09-20: the command\n * text alone scored 0.31 on a migration script that drops a column, while the\n * same call with the body scored 0.83).\n *\n * @param command - raw command text.\n * @param cfg - gate config (`cwd`, `inlineScripts`, `maxScriptBytes`).\n * @returns the state object.\n */\nexport async function buildState(command, cfg = {}) {\n  // 状态是**发给判定服务的载荷**,所以它的语言是 promptLang 而不是界面语言 lang。\n  const promptLang = normalizeLang(cfg.promptLang) ?? FALLBACK_LANG\n  const state = { [tIn(promptLang, 'gate.state.command')]: command }\n  if (cfg.inlineScripts === false) return state\n  const cwd = cfg.cwd ?? process.cwd()\n  const maxBytes = cfg.maxScriptBytes ?? 8192\n\n  const pkgName = packageScriptName(command)\n  if (pkgName !== undefined) {\n    const body = await lookupPackageScript(pkgName, cwd)\n    if (body !== undefined) {\n      state[tIn(promptLang, 'gate.state.pkgScript')] = `\"${pkgName}\": ${body}`\n      const inner = scriptTarget(body)\n      if (inner !== undefined) {\n        const innerPath = isAbsolute(inner) ? inner : resolvePath(cwd, inner)\n        const read = await readSmallText(innerPath, maxBytes, promptLang)\n        if (read.text !== undefined) {\n          state[tIn(promptLang, 'gate.state.pkgScriptBody')] = truncate(read.text, maxBytes, promptLang)\n        }\n      }\n    }\n  }\n\n  const target = scriptTarget(command)\n  if (target !== undefined) {\n    const path = isAbsolute(target) ? target : resolvePath(cwd, target)\n    const read = await readSmallText(path, maxBytes, promptLang)\n    const scriptKey = tIn(promptLang, 'gate.state.script')\n    if (read.text !== undefined) state[scriptKey] = truncate(read.text, maxBytes, promptLang)\n    else if (read.skipped !== undefined) state[scriptKey] = tIn(promptLang, 'gate.state.notRead', { why: read.skipped })\n  }\n  return state\n}\n\nfunction truncate(text, maxBytes, promptLang = FALLBACK_LANG) {\n  return text.length <= maxBytes ? text : `${text.slice(0, maxBytes)}\\n${tIn(promptLang, 'gate.truncated')}`\n}\n\n/* ------------------------------------------------------------------ *\n * 4. Jev call\n * ------------------------------------------------------------------ */\n\n/**\n * Ask Jev the one validated question about one command state.\n * @param state - the state object (see {@link buildState}).\n * @param cfg - resolved gate config (apiKey required).\n * @param signal - optional external cancellation (combined with the timeout).\n * @returns the answer probability plus the model that answered.\n */\nexport async function callJev(state, cfg, signal) {\n  if (!cfg.apiKey) {\n    const error = new Error('no TypeSafe API key resolved')\n    error.code = 'no-key'\n    throw error\n  }\n  const timeout = AbortSignal.timeout(cfg.timeoutMs)\n  const combined = signal ? AbortSignal.any([signal, timeout]) : timeout\n  const body = {\n    model: cfg.model,\n    state,\n    questions: { [QUESTION_ID]: judgeQuestion(cfg.promptLang) },\n  }\n  const res = await fetch(cfg.endpoint, {\n    method: 'POST',\n    headers: { Authorization: `Bearer ${cfg.apiKey}`, 'Content-Type': 'application/json' },\n    body: JSON.stringify(body),\n    signal: combined,\n  })\n  if (!res.ok) {\n    // 把状态码、正文与 content-type 挂在异常上:**分类器靠它们区分\"额度用完\"、\"抖了一下\"\n    // 和\"被边缘/WAF 挡下\"**,而这三者的处置完全不同(第一个停 15 分钟并告警,后两个只逐次\n    // fail-open,但原因不同 —— 见 quota.js 的 looksLikeEdgeBlock)。\n    const text = (await res.text()).slice(0, 300)\n    const error = new Error(`HTTP ${res.status}: ${text.slice(0, 200)}`)\n    error.status = res.status\n    error.body = text\n    // 边缘拦下时给的是 HTML 错误页,而应用层鉴权失败是 JSON —— 这是分辨两者最干净的信号。\n    error.contentType = res.headers?.get?.('content-type') ?? ''\n    throw error\n  }\n  const json = await res.json()\n  const answer = json?.answers?.[QUESTION_ID]\n  if (!answer || typeof answer.noul !== 'number') {\n    const error = new Error(`unexpected answer shape: ${JSON.stringify(json).slice(0, 200)}`)\n    error.code = 'shape'\n    throw error\n  }\n  // 用量只用于**成本可见性**(`guard log --stats` 会累计并折算美元),不参与判定。\n  const usage = json?.usage && typeof json.usage === 'object' ? json.usage : undefined\n  return { p: answer.noul, model: json.model ?? cfg.model, usage }\n}\n\n/* ------------------------------------------------------------------ *\n * 4. verdict\n * ------------------------------------------------------------------ */\n\n/**\n * 一次性放行令牌的挂载点。\n *\n * 位置很关键:它在**所有判定之后**,所以缓存过的 block/revise 也会重新检查令牌\n * (否则一条被判过的命令就永远无法凭令牌放行)。但 L0 的 `deny` 规则**不受令牌影响** ——\n * 那是四层设计里的硬地板,只能由人手动执行。\n *\n * @param command - 原始命令文本。\n * @param verdict - 判定结果。\n * @param cfg - 配置(`tokens`、`tokenPath`)。\n * @returns 原判定,或凭令牌改成放行后的判定(附带 token 字段便于审计)。\n */\nasync function applyToken(command, verdict, cfg) {\n  if (cfg.tokens === false || verdict.action === 'allow') return verdict\n  const token = commandToken(command)\n  if (verdict.rule?.kind === 'deny') return { ...verdict, token } // L0 硬地板:令牌不越过\n  try {\n    const grant = await consumeToken(command, { tokenPath: cfg.tokenPath })\n    if (!grant.ok) return { ...verdict, token }\n    return {\n      action: 'allow',\n      source: 'token',\n      token: grant.token,\n      overridden: verdict.action,\n      p: verdict.p,\n      rule: verdict.rule,\n      ms: verdict.ms,\n    }\n  } catch {\n    // 令牌机制出错不能让判定变形:退回原判定(保守方向)\n    return { ...verdict, token }\n  }\n}\n\n/**\n * 降级放行:不联网、不花钱,并把\"为什么\"带在判定上,让每个宿主都能转达给人。\n *\n * @param state - 降级状态。\n * @param cfg - 配置(取 degradePolicy)。\n * @param now - 当前时间。\n * @param probe - 这次是不是\"探测之后仍然失败\"的那一次。\n * @returns 判定(总是 allow)。\n */\nfunction degradedVerdict(state, cfg, now, probe = false) {\n  return {\n    action: 'allow',\n    source: 'degraded',\n    errorKind: state.kind,\n    degraded: { kind: state.kind, label: state.label, since: state.since, until: state.until, failures: state.failures },\n    warning: warningLine(state, now),\n    reason: t('quota.reason.degraded', {\n      kind: state.kind,\n      policy: t(cfg.degradePolicy === 'off' ? 'quota.policy.off' : 'quota.policy.l0-only'),\n    }),\n    probe,\n    ms: 0,\n  }\n}\n\n/**\n * 进程内记忆:哪些降级状态文件\"探测已经成功、但清不掉\"(只读文件系统 / 权限不足)。\n *\n * 为什么需要它(2026-09-23):状态文件是**唯一**的持久记忆,而删不掉它的时候,谁也改不动它。\n * 那份文件的窗口明明已经过期、服务也刚刚用一次成功判定证明自己是活的,可每条命令重读它都会\n * 得到\"探测到期\" —— 于是每条命令都被当成一次新探测,审计里反复出现 `probe`/`recovered`,\n * 而 `guard status` 永远显示\"降级中\"。既然删不掉,本进程就**不再拿它当依据**(服务回来了就是\n * 回来了),同时把\"清不掉\"这件事连同 errno 挂在发现它的那次判定上,别让原因消失。\n *\n * 键是状态文件路径,值是那份过期状态的 `until`(毫秒)。只压制**同一份或更老**的窗口:\n * 万一之后真有一份**新的**状态落盘了(比如文件系统只读是暂时的),新窗口照常生效 ——\n * 记忆绝不能顺手吃掉一次真实的降级。\n */\nconst stuckClears = new Map()\n\n/**\n * @param state - 刚刚探测成功后清不掉的那份降级状态。\n */\nfunction markClearStuck(state) {\n  if (state?.path) stuckClears.set(state.path, Number(state.until) || 0)\n}\n\n/**\n * 这份状态是不是\"已知清不掉、且已被一次成功判定证伪\"的那一份。\n * @param state - readDegraded() 的结果。\n * @returns true = 不再拿它当降级依据。\n */\nfunction isObsoleteByStuckClear(state) {\n  const stuckUntil = stuckClears.get(state?.path)\n  return stuckUntil !== undefined && Number(state.until) <= stuckUntil\n}\n\n/**\n * Decide what to do with one command.\n *\n * @param command - raw command text.\n * @param options - judge config; `apiKey` is required unless the prefilter answers.\n *   `degradePolicy: 'off'` 让整条阀门在降级期间暂停(在 L0 之前就返回);\n *   `quotaGuard: false` 可整体关掉降级检查(测试用)。\n * @returns a verdict `{ action: 'allow' | 'revise' | 'block' | 'escalate', ... }`.\n */\nexport async function evaluateCommand(command, options = {}) {\n  const cfg = { ...DEFAULTS, ...options }\n  const now = Date.now()\n  const cache = cfg.cache ?? (cfg.cache = new VerdictCache(cfg.cacheSize))\n\n  // 降级状态:先读一次,后面每个分支都用它。\n  // 读失败 = 当作没降级(宁可去问一次 API,也不要被一个坏文件卡在降级态里)。\n  let degradedState = cfg.quotaGuard === false ? null : await readDegraded(cfg)\n\n  // 本进程已经确认\"服务答得上来、只是那份状态文件删不掉\" → 不再拿它当降级依据。\n  // 没有这一步,清不掉的状态会让**每条命令**都重新走一次\"冷却到期后的探测\"(见 stuckClears)。\n  if (degradedState !== null && isObsoleteByStuckClear(degradedState)) degradedState = null\n\n  // 粘性状态(\"没有解析到密钥\")靠**条件消失**结束,不靠时间:密钥一旦能解析到,这份状态\n  // 就没有存在理由了,当场清掉。这一步零 HTTP(密钥解析是纯本地的事),所以不必等冷却、\n  // 也不必等探测窗口 —— 插上密钥后的第一条命令就恢复成正常判定。\n  // 作用域过滤只影响 isDegraded/probeDue 的判断,**不影响**这里的清除:清的是自己那条\n  // 状态文件,谁写的都该在密钥出现后消失。\n  if (degradedState !== null && isSticky(degradedState) && degradedState.kind === 'no-key' && cfg.apiKey) {\n    await clearDegraded(cfg)\n    degradedState = null\n  }\n\n  const degradedNow = isDegraded(degradedState, now, cfg.scope)\n\n  // 0. 配置要求\"降级期间整条阀门暂停\" → 在 L0 之前就放行(连免费规则也不跑)。\n  //    这是显式选择:默认的 'l0-only' 会保留免费的 L0 + 预筛。\n  if (degradedNow && cfg.degradePolicy === 'off') return degradedVerdict(degradedState, cfg, now, true)\n\n  // L0 — hard rules first, and they outrank everything below.\n  // 它**不花钱、不联网**,所以降级期间照常工作 —— 这正是默认策略的用意。\n  const rule = staticRule(command)\n  if (rule) {\n    return applyToken(command, {\n      action: rule.kind === 'deny' ? 'block' : 'escalate',\n      source: 'static-rule',\n      rule: { id: rule.id, why: rule.why, kind: rule.kind },\n      ms: 0,\n      ...(degradedNow\n        ? { degraded: { kind: degradedState.kind, until: degradedState.until }, warning: warningLine(degradedState, now) }\n        : {}),\n    }, cfg)\n  }\n\n  // L1a — provably harmless, no network.\n  const fast = prefilter(command)\n  if (fast) return { action: 'allow', source: 'prefilter', reason: fast, ms: 0 }\n\n  const key = cfg.cwd ? `${cfg.cwd}\\u0000${command}` : command\n  const cached = cache.get(key)\n  if (cached) return applyToken(command, { ...cached, source: 'cache', ms: 0 }, cfg)\n\n  // 降级窗口内(探测还没到期)→ 直接放行,不发请求。缓存过的判定在上面已经生效,\n  // 所以降级丢掉的只是\"无法再用语义层判新命令\",不是整个判定历史。\n  if (degradedNow && !probeDue(degradedState, now, cfg.scope)) return degradedVerdict(degradedState, cfg, now)\n  // 注意:探测的判据是\"有状态且已到期\",**不能**写成 `degradedNow && probeDue(...)` ——\n  // 状态到期时 isDegraded() 恰好是 false,那样写会让\"到期后的那次探测\"永远不算探测,\n  // 于是恢复与续期全部静默失效(本功能第一版就是这个错,自检当场抓到)。\n  const isProbe = degradedState !== null && probeDue(degradedState, now, cfg.scope)\n\n  const started = Date.now()\n  const commandKey = tIn(normalizeLang(cfg.promptLang) ?? FALLBACK_LANG, 'gate.state.command')\n  let state = { [commandKey]: command }\n  try {\n    state = await buildState(command, cfg)\n  } catch {\n    // enrichment is best-effort: judge the command text alone\n  }\n\n  try {\n    const { p, model, usage } = await callJev(state, cfg, cfg.signal)\n    // 探测成功 = 服务回来了 → 清掉降级状态。人不需要做任何事。\n    // 清不掉(只读文件系统 / 权限)不是\"恢复失败\":这次判定是真的,服务确实答了;但那份\n    // 过期状态文件会继续被每一次读取如实报成\"已降级\"。所以既不静默吞掉,也不假装没发生:\n    // 本进程内不再据它判断(见 stuckClears),并把 errno 挂到这次判定上。\n    const clearResult = isProbe ? await clearDegraded(cfg) : null\n    const stuck = clearResult !== null && !clearResult.ok\n    if (stuck) markClearStuck(degradedState)\n    const verdict = {\n      action: p >= cfg.highThreshold ? 'block' : p >= cfg.lowThreshold ? 'revise' : 'allow',\n      source: 'jev',\n      p,\n      model,\n      usage,\n      lowThreshold: cfg.lowThreshold,\n      highThreshold: cfg.highThreshold,\n      enriched: Object.keys(state).filter(k => k !== commandKey),\n      ms: Date.now() - started,\n      ...(isProbe ? { probe: true, recovered: true } : {}),\n      ...(stuck\n        ? {\n          clearFailed: { path: degradedState.path, code: clearResult.code, error: clearResult.error },\n          warning: t('quota.clearFailed.warning', { code: clearResult.code ?? '?', path: degradedState.path }),\n        }\n        : {}),\n    }\n    // 缓存里只放**这份判定本身** —— 同一命令在任何时刻都成立的那些字段。`usage` / `probe` /\n    // `recovered` / `clearFailed` / `warning` / `ms` 属于\"这一次调用\"的附带信息,回放它们\n    // 等于把没发生的事再记一遍(2026-09-23):\n    //   · `usage` 被回放时,`guard log --stats` 会把一次真实调用按缓存命中的次数重复计价\n    //     (实测 1 次调用、700 tokens 被算成 1400 tokens、成本翻倍);\n    //   · `probe`/`recovered` 被回放时,一条 `source: cache` 的记录会自称\"这次是一次探测\"。\n    // 所以这里显式列字段(白名单):将来判定形状长大时,新字段默认**不进**缓存,而不是被静默回放。\n    cache.set(key, {\n      action: verdict.action,\n      p: verdict.p,\n      model: verdict.model,\n      lowThreshold: verdict.lowThreshold,\n      highThreshold: verdict.highThreshold,\n      enriched: verdict.enriched,\n    })\n    return applyToken(command, verdict, cfg)\n  } catch (error) {\n    // fail-open: availability of the valve must never block the agent; the\n    // host's sandbox + approval pipeline still sits in front of the execution.\n    const { kind, status, detail } = classifyFailure(error)\n    const base = {\n      action: 'allow',\n      source: 'error',\n      errorKind: kind,\n      error: detail,\n      status,\n      ms: Date.now() - started,\n    }\n    // 持久性失败 → 进入降级:停发请求 + 留一份可读状态 + 把告警挂到这次判定上。\n    // `scope` 只对本地类(`no-key`)有意义:它决定这份状态压制谁(见 DEFAULTS.scope)。\n    if (DEGRADING_KINDS.includes(kind)) {\n      const after = await enterDegraded(kind, { cfg, now: Date.now(), detail, status, probe: isProbe, scope: cfg.scope })\n      return {\n        ...base,\n        degraded: { kind, label: after.label, since: after.since, until: after.until, failures: after.failures },\n        warning: warningLine(after, Date.now()),\n        probe: isProbe,\n      }\n    }\n    return { ...base, ...(isProbe ? { probe: true } : {}) }\n  }\n}\n\n"
    },
    {
      "path": "lib/verdict.js",
      "content": "/**\n * Verdict composition — the four states, the reason text, and the host mapping.\n *\n * Four states rather than three, because \"let the model try again\" and \"fetch a\n * human\" are different control flows: the first closes in seconds, the second can\n * take hours. Collapsing them either drags the human into trivia or lets the model\n * keep rephrasing a destructive command until one phrasing slips through.\n *\n *   allow     — provably harmless, or the judge is confident it is.\n *   revise    — not confident enough to run, but the model can likely do better.\n *               Called with three deterministic downgrade templates.\n *   block     — the judge (or an L0 rule) says this destroys something\n *               unrecoverable; not worth retrying.\n *   escalate  — needs a human: L0 says \"always confirm\", or no safer form exists.\n */\n\nimport { dirname, join } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { getLang, t } from './i18n.js'\n\n/**\n * Absolute path of the CLI entry, derived from this module's own location.\n *\n * Why computed instead of passed in: the hint we print tells the **user** to paste a\n * line into their own terminal, whose cwd is arbitrary — a bare `node bin/guard.mjs`\n * only works if they happen to sit inside the package. Deriving it here keeps every\n * caller correct with no plumbing, and stays right if the package is moved to another\n * machine. 调用方仍可用 `opts.cliPath` 覆盖(见 `adapters/dsh/index.js`)。\n */\nconst DEFAULT_CLI_PATH = join(dirname(fileURLToPath(import.meta.url)), '..', 'bin', 'guard.mjs')\n\n/** The three deterministic downgrades offered on `revise` — no model needed. */\nconst TEMPLATE_IDS = Object.freeze(['dry-run', 'narrow', 'backup-first'])\n\n/**\n * The three downgrade templates in the language in force.\n *\n * Text lives in the message catalog (it is read by the model and by a human in an\n * approval dialog), the shape stays here.\n *\n * @param lang - language; defaults to the one currently set.\n * @returns `[{ id, text, examples }]`.\n */\nexport function templates(lang = getLang()) {\n  return TEMPLATE_IDS.map((id) => {\n    const examples = []\n    for (let i = 0; ; i += 1) {\n      const key = `template.${id}.example.${i}`\n      const value = t(key)\n      if (value === key) break // no such example in any language\n      examples.push(value)\n    }\n    return { id, text: t(`template.${id}.text`), examples }\n  })\n}\n\n/**\n * 把文本包成\"可以在目标 shell 里整行复制粘贴\"的形式。\n *\n * **必须按平台分叉。** POSIX 的 `'…'` 里用 `'\\''` 转义单引号;PowerShell 的 `'…'` 里靠\n * **写两个单引号**转义。两者不通用 —— 在 PowerShell 里贴 POSIX 那种写法会直接解析失败\n * (而这段话是给用户照抄的,失败就等于授权入口不可用)。cmd.exe 则两种都不支持,\n * 所以另给了与 shell 无关的入口:`guard allow --command-file <文件>`。\n *\n * 默认用**本进程所在平台**:DSH 跑在 WSL 上时,用户能粘贴的终端通常也是 WSL/POSIX;\n * DSH 跑在 Windows 上时,那是 PowerShell。这与\"宿主和终端在同一侧\"的常见部署一致。\n *\n * @param value - 任意文本(命令原文里可能有引号、中文、换行)。\n * @param platform - `process.platform` 的取值;默认取当前进程。\n * @returns 可直接粘进目标 shell 的字符串。\n */\nexport function shellQuote(value, platform = process.platform) {\n  const text = String(value)\n  if (platform === 'win32') return `'${text.replace(/'/g, \"''\")}'`\n  return `'${text.replace(/'/g, \"'\\\\''\")}'`\n}\n\n/**\n * 目标 shell 的名字,写进给人看的提示里(尤其是要让用户知道该开哪个终端)。\n * @param platform - `process.platform` 的取值。\n * @returns 名字。\n */\nexport function shellName(platform = process.platform) {\n  return platform === 'win32' ? 'PowerShell' : t('verdict.shell.posix')\n}\n\n/**\n * @typedef {{ action: 'allow'|'revise'|'block'|'escalate', source: string, p?: number,\n *   model?: string, ms?: number, rule?: {id: string, why: string, kind?: 'deny'|'ask'},\n *   reason?: string, templates?: ReturnType<typeof templates>, enriched?: string[],\n *   error?: string, token?: string, warning?: string }} Verdict\n */\n\n/**\n * One-line explanation for a verdict, safe to show to a human or a model.\n * @param command - the command under judgement.\n * @param verdict - the verdict to explain.\n * @param opts - `{ policy, token, cliPath, platform }`: `policy` decides what \"escalate\"\n *   means for this session (see below) and, with `never`, makes a non-allow reason state\n *   that this was an automatic decision so the model does not believe a human looked at it\n *   and said no. `cliPath` overrides the absolute CLI path used in the one-shot-token hint.\n *   `platform` overrides `process.platform` for the shell-quoting style of that hint.\n * @returns the reason text.\n */\nexport function explain(command, verdict, opts = {}) {\n  const pct = verdict.p === undefined ? undefined : `${(verdict.p * 100).toFixed(1)}%`\n  const detail = verdict.rule\n    ? t('verdict.detail.rule', { id: verdict.rule.id, why: verdict.rule.why })\n    // 降级放行**不是**预筛判定出来的,不能复用那句文案 —— 否则读者会以为这条被确认过无害。\n    : verdict.source === 'degraded' ? t('verdict.detail.degraded')\n      : verdict.p === undefined ? t('verdict.detail.prefilter') : t('verdict.detail.probability', { pct })\n  // 宿主真的会弹审批框吗?这个状态**由调用方显式告知**(`opts.routedToHuman`,见 toHostDecision):\n  // 因为同一动作在不同的审批策略下会走到不同的出口(revise/block 在 ask 模式下转人工,在\n  // never 模式下仍是拒绝)。缺省推导保持旧行为(仅 escalate + ask),供 CLI / selftest 这类\n  // 不经过路由的调用使用。\n  // 读者是**弹窗**里的人和后面可能看到拒绝的模型 —— 不能说\"本会话没有审批提示\"。\n  // 实测(2026-09-20,ask 模式)弹窗里原样显示的就是那句旧文案,指着眼前的弹窗说没有弹窗,\n  // 还让用户复制一条终端命令 —— 所以这里按路由结果分叉。\n  const prompted = opts.routedToHuman ?? (opts.policy === 'ask' && verdict.action === 'escalate')\n  const askWait = t('verdict.askWait')\n  const head = {\n    allow: t('verdict.head.allow'),\n    revise: prompted ? t('verdict.head.prompted') : t('verdict.head.revise'),\n    block: prompted ? t('verdict.head.prompted') : t('verdict.head.block'),\n    escalate: t('verdict.head.prompted'),\n  }[verdict.action] ?? verdict.action\n  const tail = {\n    allow: '',\n    revise: prompted ? askWait : t('verdict.tail.revise'),\n    // 带 L0 `deny` 规则的 block 永远不会转人工,所以这里再挡一层:万一调用方传错,\n    // 也不能对着一条不可逆的硬规则说\"等用户在弹窗里决定\"。\n    block: prompted && verdict.rule?.kind !== 'deny' ? askWait : t('verdict.tail.block'),\n    escalate: prompted ? askWait : t('verdict.tail.escalate'),\n  }[verdict.action] ?? ''\n  const auto = opts.policy === 'never' && verdict.action !== 'allow' ? t('verdict.autoNote') : ''\n  // 降级告警:额度/密钥出问题时,理由必须自己说明\"这一条没经过语义判定\"。\n  // 否则读者会把\"L0 拦下的一条\"误当成\"完整判定下的一条\",也会把放行当成\"判定过是安全的\"。\n  const warn = verdict.warning ? ` ${verdict.warning}` : ''\n  // 一次性放行令牌:只在\"非 allow、不是 L0 硬规则、且宿主不会真的弹审批框\"时附上\n  // (见 token.js 的设计说明)。\n  // 为什么排除 prompted:那时人就在弹窗前面,再给一条\"复制到终端授权\"的路只会互相打架\n  // —— 实测弹窗里两条路同时出现,读者不知道该走哪条。\n  // 提示里的命令**不能截断** —— 令牌是对完整命令文本求哈希的,截断后用户授予的令牌就匹配不上。\n  // 引号按**平台**分叉(POSIX 的 `'\\''` 与 PowerShell 的 `''` 不通用);Windows 上额外点明\n  // 该开哪个终端,因为 cmd.exe 两种写法都不认 —— 那种情况走 `allow --command-file`。\n  const platform = opts.platform ?? process.platform\n  const token = opts.token && verdict.action !== 'allow' && verdict.rule?.kind !== 'deny' && !prompted\n    ? t('verdict.tokenHint', {\n      winNote: platform === 'win32' ? t('verdict.winNote') : '',\n      cli: opts.cliPath || DEFAULT_CLI_PATH,\n      quoted: shellQuote(command, platform),\n      token: opts.token,\n    })\n    : ''\n  return t('verdict.line', {\n    head,\n    detail,\n    tail,\n    auto,\n    warn,\n    token,\n    command: command.length > 300 ? `${command.slice(0, 300)}…` : command,\n  })\n}\n\n/**\n * Map a verdict onto the DSH-shaped typed decision.\n *\n * DSH's `ask` resolves through `ctx.approval`; under the `danger-full-access`\n * preset the approval policy is `never`, where every ask becomes a *rejection*\n * carrying the misleading reason \"the user rejected tool bash\". So when approvals\n * are off we deny directly, with an accurate reason the model can act on.\n *\n * **路由随审批策略分叉**(2026-09-20 用户决定):`never`(= 全自动,没人可问)下\n * `revise`/`block` 一律拒绝;`ask`(人就在场)下两者都转人工审批 —— 灰区本来就\"证据不足\",\n * 让一个 50% 的判断替人做决定没有道理。宿主无应答者时审批是 fail-closed,所以转人工\n * **不会**在无人值守时变成自动放行。\n *\n * **唯一例外**是带 L0 `deny` 规则的硬命中(`rm -rf /`、`mkfs`、`git push --force` 这类\n * 零误报的不可逆操作):两种模式都直接拒绝,既不转人工也不发一次性令牌(见 D5/D13)。\n *\n * @param command - the command under judgement.\n * @param verdict - the composed verdict.\n * @param approvalPolicy - `'ask' | 'never'` for this session.\n * @param opts - `{ token, cliPath, reviseInAskMode, blockInAskMode }`:一次性放行令牌会被写进\n *   理由里(见 token.js);`cliPath` 透传给 {@link explain};后两个是 `'ask' | 'deny'` 的路由开关。\n * @returns `{ kind: 'allow' } | { kind: 'ask', reason } | { kind: 'deny', reason }`.\n */\nexport function toHostDecision(command, verdict, approvalPolicy = 'ask', opts = {}) {\n  const reviseInAskMode = opts.reviseInAskMode ?? 'ask'\n  const blockInAskMode = opts.blockInAskMode ?? 'ask'\n  const hardRule = verdict.rule?.kind === 'deny'\n  const toHuman = approvalPolicy === 'ask' && hardRule !== true\n    && (verdict.action === 'escalate'\n      || (verdict.action === 'revise' && reviseInAskMode === 'ask')\n      || (verdict.action === 'block' && blockInAskMode === 'ask'))\n  const reason = explain(command, verdict, {\n    policy: approvalPolicy,\n    token: opts.token ?? verdict.token,\n    cliPath: opts.cliPath,\n    routedToHuman: toHuman,\n  })\n  if (verdict.action === 'allow') return { kind: 'allow' }\n  // revise and block are model-facing denials when nobody can be asked; revise additionally teaches.\n  return toHuman ? { kind: 'ask', reason } : { kind: 'deny', reason }\n}\n\n/**\n * The full text handed to a model on `revise`, including the templates.\n * @param command - the command under judgement.\n * @param verdict - a `revise` verdict.\n * @param opts - `{ policy }`, forwarded to {@link explain}.\n * @returns multi-line guidance.\n */\nexport function reviseGuidance(command, verdict, opts = {}) {\n  const lines = [explain(command, verdict, opts), '', t('verdict.reviseHeading')]\n  // 循环变量不要叫 `t` —— 它会遮住 i18n 的查表函数。\n  for (const tpl of templates()) {\n    lines.push(t('verdict.templateLine', { text: tpl.text, examples: tpl.examples.join(' / ') }))\n  }\